import{_ as d,c as a,o as r,b0 as e}from"./chunks/framework.C5ev1SXp.js";const o="/scm-docs/assets/channel-map.BHMVBLqe.svg",S=JSON.parse('{"title":"LV001-调试与跟踪概述","description":null,"frontmatter":{"title":"LV001-调试与跟踪概述","date":"2026-11-20T09:22:34.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/dev-tool/debug-and-trace/126d68dda84a1ac0c5d2e6c4","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-11-20T09:22:34.428Z","fulluuid":"0c5d2e6c448a417b972ce7386d47424e","useduuid":"0c5d2e6c4"}},"headers":[],"relativePath":"sdoc/dev-tool/debug-and-trace/126d68dda84a1ac0c5d2e6c4.md","filePath":"sdoc/01-开发工具/20-调试与跟踪/LV001-调试与跟踪概述.md","lastUpdated":1795182794000}'),h={name:"sdoc/dev-tool/debug-and-trace/126d68dda84a1ac0c5d2e6c4.md"};function i(n,t,l,s,c,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="lv001-调试与跟踪概述" tabindex="-1">LV001-调试与跟踪概述 <a class="header-anchor" href="#lv001-调试与跟踪概述" aria-label="Permalink to &quot;LV001-调试与跟踪概述&quot;">​</a></h1><h2 id="一、-基础概念" tabindex="-1">一、 基础概念 <a class="header-anchor" href="#一、-基础概念" aria-label="Permalink to &quot;一、 基础概念&quot;">​</a></h2><p>调试要回答的问题只有一个：<strong>程序运行时，芯片内部到底发生了什么</strong>。把答案取出来，全部手段只有四条来路（见第二章）。本章按四步把这层基础铺齐：先分清调试与跟踪两种<strong>手段</strong>，再沿 CoreSight 链路认清各层<strong>名词</strong>，然后认识链路上的探针与软件<strong>器材</strong>，最后收束到 STM32F103 的能力<strong>边界</strong>——绝大多数&quot;调试工具怎么选&quot;的迷茫，根源都是这四步没走稳。</p><h3 id="_1-调试与跟踪-一对互补的视角" tabindex="-1">1. 调试与跟踪：一对互补的视角 <a class="header-anchor" href="#_1-调试与跟踪-一对互补的视角" aria-label="Permalink to &quot;1. 调试与跟踪：一对互补的视角&quot;">​</a></h3><p>本篇标题里的两个词，经常被连在一起说，但它们对 CPU 的态度<strong>完全相反</strong>。理解了这一对立，后面四条通道的分类立刻清晰。</p><h4 id="_1-1-调试-以停机换现场" tabindex="-1">1.1 调试：以停机换现场 <a class="header-anchor" href="#_1-1-调试-以停机换现场" aria-label="Permalink to &quot;1.1 调试：以停机换现场&quot;">​</a></h4><p>调试（Debug）是<strong>侵入式</strong>的：调试器通过调试口把 CPU 挂起，在暂停的瞬间读出全部寄存器、内存与外设状态，得到一份<strong>完整快照</strong>。断点、单步、变量窗口都属于这一类。</p><p>它能回答&quot;此刻到底发生了什么&quot;，但代价是：被暂停的这段时间里，真实世界还在跑——外设还在收发、中断还在触发，停下再看的已经不是连续的世界。凡是时序敏感的问题（中断丢没丢、两件事谁先谁后），停机调试天然无能为力。</p><h4 id="_1-2-跟踪-以通道换连续性" tabindex="-1">1.2 跟踪：以通道换连续性 <a class="header-anchor" href="#_1-2-跟踪-以通道换连续性" aria-label="Permalink to &quot;1.2 跟踪：以通道换连续性&quot;">​</a></h4><p>跟踪（Trace）是<strong>非侵入式</strong>的：CPU 不停，运行信息通过某种通道持续送出来，换来的是<strong>连续记录</strong>。代价是只能拿到通道允许的内容——统计计数、事件包、日志文本——而不是完整现场。</p><p>本篇的四条通道里，只有第一条（停机读内存）属于纯调试，其余三条都在跟踪这一侧，区别只在&quot;数据从哪里来&quot;：芯片里算好的统计、程序主动打包送出的日志、探头直接量的电平。</p><h4 id="_1-3-一句话区分" tabindex="-1">1.3 一句话区分 <a class="header-anchor" href="#_1-3-一句话区分" aria-label="Permalink to &quot;1.3 一句话区分&quot;">​</a></h4><p><strong>调试拿现场，跟踪拿过程</strong>。工程里真正的排查往往是两者交替：先用跟踪缩小范围，再用调试拿现场定性。</p><h3 id="_2-coresight-五层链路" tabindex="-1">2. CoreSight 五层链路 <a class="header-anchor" href="#_2-coresight-五层链路" aria-label="Permalink to &quot;2. CoreSight 五层链路&quot;">​</a></h3><p>四条通道都建立在 ARM 的 <strong>CoreSight</strong> 架构之上。CoreSight 不是某个具体硬件，而是 ARM 定义的一整套<strong>片上调试与跟踪体系</strong>——一族可授权的 IP 组件加互联协议的统称：调试访问口（DAP）、断点单元（FPB）、数据观察与计数（DWT）、跟踪打包（ITM/ETM）、跟踪输出（TPIU/SWO）都出自这套体系，组件之间用 ATB 总线（Advanced Trace Bus）搬运跟踪数据。芯片厂商按需裁剪集成，所以同为 CoreSight，F103 只实现了其中一部分（没有 ETM，见本章 4 节）。</p><p>把这套体系从 PC 上的 IDE 到芯片内部的调试单元自上而下摆开，可以看成五层。拿到一个名词时先问&quot;它是软件、设备还是协议&quot;，落在哪一层，名字就不会混——下面自上而下挑三层最容易混的展开。</p><h4 id="_2-1-各层职责" tabindex="-1">2.1 各层职责 <a class="header-anchor" href="#_2-1-各层职责" aria-label="Permalink to &quot;2.1 各层职责&quot;">​</a></h4><table tabindex="0"><thead><tr><th>层</th><th>组成</th><th>作用</th></tr></thead><tbody><tr><td>工具层</td><td>uVision、J-Scope、SystemView、串口助手</td><td>在 PC 上展示与解析</td></tr><tr><td>探针层</td><td>J-Link、ST-Link、ULINK、CMSIS-DAP</td><td>USB ↔ 调试协议的翻译设备</td></tr><tr><td>传输层</td><td>SWD（SWDIO/SWCLK）、JTAG</td><td>探针与芯片之间的协议与时序</td></tr><tr><td>访问层</td><td>DAP、FPB（断点单元）、DWT（观察点）</td><td>读内存、暂停 CPU、监视地址</td></tr><tr><td>跟踪层</td><td>ITM、DWT 计数器、TPIU/SWO</td><td>把运行信息单向送出芯片</td></tr></tbody></table><h4 id="_2-2-传输层-swd-与-jtag-是协议-不是设备" tabindex="-1">2.2 传输层：SWD 与 JTAG 是协议，不是设备 <a class="header-anchor" href="#_2-2-传输层-swd-与-jtag-是协议-不是设备" aria-label="Permalink to &quot;2.2 传输层：SWD 与 JTAG 是协议，不是设备&quot;">​</a></h4><p>最常见的混淆是把 J-Link 和 SWD 并列着说——<strong>J-Link 是设备（探针层），SWD 是协议（传输层），两者隔着整整一层</strong>。SWD 与 JTAG 都只解决&quot;探针怎么和芯片对话&quot;这一层的事：</p><ul><li>SWD 两根线：<code>SWDIO</code> 双向数据、<code>SWCLK</code> 时钟</li><li>JTAG 四到五根线：<code>TCK</code>/<code>TMS</code>/<code>TDI</code>/<code>TDO</code>，可选 <code>TRST</code></li></ul><p>STM32 内部的 <code>SWJ-DP</code> 同时实现了两个调试口，上电默认 JTAG，可以发一段固定的 SWJ 切换序列切到 SWD 以省引脚。注意<strong>同一时刻只有一条链路是活的</strong>，不能同时用。</p><h4 id="_2-3-探针层与访问层-设备与-门房" tabindex="-1">2.3 探针层与访问层：设备与&quot;门房&quot; <a class="header-anchor" href="#_2-3-探针层与访问层-设备与-门房" aria-label="Permalink to &quot;2.3 探针层与访问层：设备与&quot;门房&quot;&quot;">​</a></h4><p>探针（J-Link、ST-Link 等）是探针层设备，负责把 PC 的 USB 命令翻译成 SWD/JTAG 时序；芯片那一端由访问层的 <strong>DAP</strong>（调试访问端口）接住，再经访问口去读写内存与内核寄存器（FPB、DWT 都在这个空间里）。</p><p>一个探针号称&quot;同时支持 SWD 和 JTAG&quot;，只是它内部做了两套协议引擎、界面里二选一，并不是能同时跑两种协议。</p><p>探针有哪些产品、各配什么软件，见本章第 3 节。</p><h4 id="_2-4-跟踪层-itm-产生、tpiu-封装、swo-运输" tabindex="-1">2.4 跟踪层：ITM 产生、TPIU 封装、SWO 运输 <a class="header-anchor" href="#_2-4-跟踪层-itm-产生、tpiu-封装、swo-运输" aria-label="Permalink to &quot;2.4 跟踪层：ITM 产生、TPIU 封装、SWO 运输&quot;">​</a></h4><p>三个名字经常被搅在一起，其实是一条流水线上的三站：</p><ul><li><strong>ITM</strong>（指令跟踪宏单元）：<strong>产生</strong>数据——程序写 <code>ITM_STIM</code> 寄存器，它把内容打成跟踪包</li><li><strong>TPIU</strong>（跟踪端口接口单元）：<strong>封装</strong>数据——把 ITM/DWT 的包串行化</li><li><strong>SWO</strong>：<strong>运输</strong>数据——TPIU 的 SWO 模式从一根线（<code>PB3</code>/TRACESWO）单向送出芯片，有 Manchester 与 NRZ 两种编码，波特率要与探针约定一致</li></ul><p>特别提醒：SWO 与 SWD 是两条独立的路。SWD 双向、能读写内存；SWO 单向、只往外吐数据，且需要探针支持（J-Link、板载 ST-Link V2-1 支持，很多廉价 ST-Link V2 克隆不支持）。</p><h3 id="_3-探针与配套软件" tabindex="-1">3. 探针与配套软件 <a class="header-anchor" href="#_3-探针与配套软件" aria-label="Permalink to &quot;3. 探针与配套软件&quot;">​</a></h3><p>五层链路里，探针层是唯一需要额外掏钱买的&quot;盒子&quot;，而工具层软件又常常与探针绑定——<strong>买探针，实际是在买&quot;硬件 + 一整套 PC 端软件生态&quot;</strong>。所以按厂商认识器材最省事：每家一圈，硬件与软件一起看。</p><h4 id="_3-1-四类常见探针" tabindex="-1">3.1 四类常见探针 <a class="header-anchor" href="#_3-1-四类常见探针" aria-label="Permalink to &quot;3.1 四类常见探针&quot;">​</a></h4><table tabindex="0"><thead><tr><th>探针</th><th>出品方</th><th>支持范围</th><th>SWO</th><th>价位</th><th>一句话定位</th></tr></thead><tbody><tr><td>J-Link</td><td>SEGGER</td><td>几乎所有 Cortex-M/R/A，上万型号</td><td>支持</td><td>高</td><td>全能型，事实标准</td></tr><tr><td>ST-Link</td><td>ST</td><td>仅 STM32（SWD）与 STM8（SWIM）</td><td>V2 及以后支持</td><td>低</td><td>官方廉价方案，板载常见</td></tr><tr><td>ULINK</td><td>ARM/Keil</td><td>Cortex-M 全系（配 MDK）</td><td>支持</td><td>高</td><td>MDK 官方配套</td></tr><tr><td>CMSIS-DAP</td><td>ARM 开放标准</td><td>取决于固件实现</td><td>多数支持</td><td>极低</td><td>开源标准，人人可造</td></tr></tbody></table><h4 id="_3-2-j-link-全能型事实标准" tabindex="-1">3.2 J-Link：全能型事实标准 <a class="header-anchor" href="#_3-2-j-link-全能型事实标准" aria-label="Permalink to &quot;3.2 J-Link：全能型事实标准&quot;">​</a></h4><p>SEGGER 出品，覆盖最广：Cortex-M/R/A 全系外加一批其他内核，主流 IDE（MDK、IAR、CubeIDE、VS Code）全部原生支持。硬件从 BASE 到 PLUS、ULTRA+、PRO 档位递增（SWD 时钟、trace 带宽、接口数量逐级提高），日常开发 BASE 一档足够。</p><p>PC 端软件包免费，装一次五件套全有：</p><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td>J-Flash</td><td>独立烧录工具（擦/写/校验/回读 Flash）</td></tr><tr><td>J-Link Commander</td><td>命令行读写内存与寄存器，快速验证连接</td></tr><tr><td>RTT Viewer</td><td>查看 RTT 日志（RTT = Real-Time Transfer，SEGGER 的实时日志技术，RAM 缓冲 + 调试器后台搬运，详见第二章 4.3）</td></tr><tr><td>J-Scope</td><td>变量曲线（见第二章 6.1）</td></tr><tr><td>GDB Server</td><td>给 VS Code/GDB 前端当调试后端</td></tr></tbody></table><p>其中 <strong>J-Flash</strong> 值得单独认识：它是脱离 IDE 的量产级烧录器——支持 hex/s19/bin 格式，擦、写、校验、回读一键完成，还能配 <code>.jflash</code> 工程文件走命令行自动化（产线批量烧录就是这么干的）。日常调试在 IDE 里点下载就够，产线和批量操作才轮到它上场。</p><p>最后提醒：J-Link 山寨货泛滥，廉价克隆升级官方固件后会被 SEGGER 检测拒绝或限速，量产环境别贪这个便宜。</p><h4 id="_3-3-st-link-官方廉价方案" tabindex="-1">3.3 ST-Link：官方廉价方案 <a class="header-anchor" href="#_3-3-st-link-官方廉价方案" aria-label="Permalink to &quot;3.3 ST-Link：官方廉价方案&quot;">​</a></h4><p>ST 官方出品，只服务自家芯片：STM32 走 SWD，STM8 走 SWIM。价格亲民，且大量 ST 开发板（Nucleo、Discovery）直接板载，到手即用。</p><p>硬件代际：V1（早期）→ V2（独立/板载）→ V2-1（Nucleo 板载，多了一个 USB 虚拟串口，调试口和串口日志一根 USB 线全解决）→ V3（多接口、可接多目标）。SWO 正版 V2 及以后都支持，廉价克隆常没把 SWO 线引出来。</p><p>配套软件三件：</p><ul><li><strong>STM32CubeProgrammer</strong>：现行官方烧录工具，GUI + CLI 双形态，支持 ST-Link/串口/USB DFU 多种连接</li><li><strong>ST-LINK Utility</strong>：上一代工具，已停止更新，官方建议迁移到 CubeProgrammer</li><li><strong>STM32CubeIDE</strong>：ST 官方 IDE，内置调试（OpenOCD 后端），免费</li></ul><h4 id="_3-4-ulink、cmsis-dap-与开源工具链" tabindex="-1">3.4 ULINK、CMSIS-DAP 与开源工具链 <a class="header-anchor" href="#_3-4-ulink、cmsis-dap-与开源工具链" aria-label="Permalink to &quot;3.4 ULINK、CMSIS-DAP 与开源工具链&quot;">​</a></h4><ul><li><strong>ULINK</strong>：ARM/Keil 自家探针，与 MDK 深度绑定，国内用量不大</li><li><strong>CMSIS-DAP</strong>：ARM 开放的固件标准（开源实现叫 DAPLink），任何厂商都能做，淘宝几十元的 &quot;DAP-Link&quot; 小板就是它；配 OpenOCD/pyOCD/MDK 使用，速度一般但免驱、无版权风险</li></ul><p>后两者常与开源工具链搭配：OpenOCD 与 pyOCD 是开源调试服务器，横跨多种探针（ST-Link、CMSIS-DAP 都认），是 VS Code + Cortex-Debug 插件方案的后端。&quot;DAP-Link 探针 + OpenOCD&quot;是纯开源组合；J-Link 一般直接用自家驱动，不走这条路。</p><h4 id="_3-5-本工程的器材" tabindex="-1">3.5 本工程的器材 <a class="header-anchor" href="#_3-5-本工程的器材" aria-label="Permalink to &quot;3.5 本工程的器材&quot;">​</a></h4><p>本工程在用的是 <strong>J-Link + MDK</strong>：烧录与断点调试走 J-Link，第二章 4 节的 RTT、SWO 扩展能力需要时随时可启用。</p><h3 id="_4-stm32f103-的能力边界" tabindex="-1">4. STM32F103 的能力边界 <a class="header-anchor" href="#_4-stm32f103-的能力边界" aria-label="Permalink to &quot;4. STM32F103 的能力边界&quot;">​</a></h3><h4 id="_4-1-手里有什么" tabindex="-1">4.1 手里有什么 <a class="header-anchor" href="#_4-1-手里有什么" aria-label="Permalink to &quot;4.1 手里有什么&quot;">​</a></h4><ul><li>硬件断点：FPB 提供 <strong>6 个</strong>比较器</li><li>数据观察点：DWT 提供 <strong>4 个</strong>比较器，其中只有 <code>COMP0</code> 能用于 PC 匹配</li><li>跟踪：ITM、TPIU/SWO、DWT 周期计数器（CYCCNT）齐全</li></ul><h4 id="_4-2-没有-etm-意味着什么" tabindex="-1">4.2 没有 ETM 意味着什么 <a class="header-anchor" href="#_4-2-没有-etm-意味着什么" aria-label="Permalink to &quot;4.2 没有 ETM 意味着什么&quot;">​</a></h4><p><strong>F103 没有 ETM</strong>（嵌入式跟踪宏单元），拿不到完整的指令流 trace。PC 采样只能靠调试器轮询 <code>DWT_PCSR</code> 或 SWO 事件包，是&quot;抽样统计&quot;，看不到每一条指令的执行。想看完整指令流，需要带 ETM 的芯片（如 F4/F7/H7 部分型号）加配套探针。</p><h2 id="二、-四条数据通道" tabindex="-1">二、 四条数据通道 <a class="header-anchor" href="#二、-四条数据通道" aria-label="Permalink to &quot;二、 四条数据通道&quot;">​</a></h2><h3 id="_1-全景总览" tabindex="-1">1. 全景总览 <a class="header-anchor" href="#_1-全景总览" aria-label="Permalink to &quot;1. 全景总览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>通道</th><th>停不停 CPU</th><th>数据怎么出来</th><th>典型手段</th><th>详见</th></tr></thead><tbody><tr><td>一、停机读内存</td><td><strong>停</strong></td><td>CPU 暂停后，DAP 直接读 RAM 与寄存器</td><td>断点、单步、变量窗口、调用栈</td><td>本章 2</td></tr><tr><td>二、芯片内统计</td><td>不停</td><td>内核或软件把结果留在寄存器/RAM，再由 DAP 读出</td><td>CYCCNT、PC 采样、RTOS 统计</td><td>本章 3</td></tr><tr><td>三、芯片外送</td><td>不停</td><td>程序主动打包，从 SWO 或串口送出去</td><td>printf、ITM、RTT</td><td>本章 4</td></tr><tr><td>四、芯片外测量</td><td>不停</td><td>不经过任何调试通道，用探头直接量引脚</td><td>GPIO 打点 + 逻辑分析仪</td><td>本章 5</td></tr></tbody></table><p><img src="'+o+'" alt="调试与跟踪的四条数据通道"></p><p>四者的取舍只在<strong>代价</strong>：停机能拿到最全的现场，但实时性归零；后三条不停机，代价分别是&quot;只有统计值&quot;&quot;占带宽&quot;&quot;要额外硬件&quot;。</p><p>还有一类工具——J-Scope、SystemView、MDK Logic Analyzer——只是把第二、三条通道的数据画成图，<strong>不改变数据的来路</strong>，所以不算第五条通道，单列本章 6 节。</p><h3 id="_2-通道一-停机读内存" tabindex="-1">2. 通道一：停机读内存 <a class="header-anchor" href="#_2-通道一-停机读内存" aria-label="Permalink to &quot;2. 通道一：停机读内存&quot;">​</a></h3><p>CPU 暂停后，DAP 可以读写整个地址空间——变量、外设寄存器、栈，看到的是<strong>某一时刻的完整快照</strong>。代价是实时性归零，长跑程序无法使用。</p><h4 id="_2-1-断点" tabindex="-1">2.1 断点 <a class="header-anchor" href="#_2-1-断点" aria-label="Permalink to &quot;2.1 断点&quot;">​</a></h4><p>断点是这一通道的入口：让 CPU 在指定位置停下来，把现场交给调试器。实现上有硬件、软件两种，各有边界。</p><h5 id="_2-1-1-硬件断点-fpb" tabindex="-1">2.1.1 硬件断点（FPB） <a class="header-anchor" href="#_2-1-1-硬件断点-fpb" aria-label="Permalink to &quot;2.1.1 硬件断点（FPB）&quot;">​</a></h5><p>FPB 的 6 个比较器实时比对取指地址，命中即挂起 CPU。不修改代码本身，Flash 与 RAM 中的代码都能用。</p><ul><li>能查什么：执行到某行/某函数时停下看现场</li><li>前提：SWD 连接</li><li>代价：数量只有 6 个；代码优化后行号与指令的对应会漂移</li></ul><h5 id="_2-1-2-软件断点-bkpt" tabindex="-1">2.1.2 软件断点（BKPT） <a class="header-anchor" href="#_2-1-2-软件断点-bkpt" aria-label="Permalink to &quot;2.1.2 软件断点（BKPT）&quot;">​</a></h5><p>调试器把断点处的原指令替换为 <code>BKPT</code> 指令，命中时触发调试异常。它不占用 FPB 比较器，但<strong>要求该处内存可写</strong>——只适用于 RAM 中运行的代码。Flash 里的代码不能随手改写，所以在 Flash 代码上设断点，调试器实际还是落到硬件断点上。</p><h5 id="_2-1-3-取舍" tabindex="-1">2.1.3 取舍 <a class="header-anchor" href="#_2-1-3-取舍" aria-label="Permalink to &quot;2.1.3 取舍&quot;">​</a></h5><p>Flash 程序（本工程的常态）实际可用的就是 6 个硬件断点；RAM 调试器代码（如 bootloader 搬运场景）可以享受&quot;无限&quot;软件断点。</p><h4 id="_2-2-单步执行" tabindex="-1">2.2 单步执行 <a class="header-anchor" href="#_2-2-单步执行" aria-label="Permalink to &quot;2.2 单步执行&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模式</th><th>行为</th><th>适用</th></tr></thead><tbody><tr><td>源码级单步</td><td>一次执行一行 C 代码</td><td>跟踪高级逻辑</td></tr><tr><td>汇编级单步</td><td>一次执行一条指令</td><td>精确观察寄存器、分析优化后的代码</td></tr></tbody></table><p>代价都是极慢、实时性为零，只适合小范围定点观察。</p><h4 id="_2-3-变量、内存与寄存器查看" tabindex="-1">2.3 变量、内存与寄存器查看 <a class="header-anchor" href="#_2-3-变量、内存与寄存器查看" aria-label="Permalink to &quot;2.3 变量、内存与寄存器查看&quot;">​</a></h4><table tabindex="0"><thead><tr><th>手段</th><th>能查什么</th><th>代价</th></tr></thead><tbody><tr><td>变量/内存窗口</td><td>任意变量与内存区域的当前值</td><td>只在停机时刷新</td></tr><tr><td>外设寄存器窗口</td><td>USART/GPIO/FSMC 等寄存器逐位含义</td><td>需对照参考手册理解位定义</td></tr></tbody></table><h4 id="_2-4-数据观察点-dwt" tabindex="-1">2.4 数据观察点（DWT） <a class="header-anchor" href="#_2-4-数据观察点-dwt" aria-label="Permalink to &quot;2.4 数据观察点（DWT）&quot;">​</a></h4><p>回答&quot;<strong>谁</strong>在改这个变量&quot;：DWT 的 4 个比较器按地址匹配，命中即停机。注意它按地址匹配、不比数据值——变量被写成了相同的值也会命中。比较器的匹配机制详见 <a href="./../LV004-DWT调试单元.html">LV004-DWT调试单元</a>。</p><p>严格说观察点&quot;命中前&quot;不停机，但它命中后的动作是让 CPU 停下（或产生 trace 包），所以归在停机这一通道。</p><h4 id="_2-5-调用栈与故障现场" tabindex="-1">2.5 调用栈与故障现场 <a class="header-anchor" href="#_2-5-调用栈与故障现场" aria-label="Permalink to &quot;2.5 调用栈与故障现场&quot;">​</a></h4><h5 id="_2-5-1-调用栈" tabindex="-1">2.5.1 调用栈 <a class="header-anchor" href="#_2-5-1-调用栈" aria-label="Permalink to &quot;2.5.1 调用栈&quot;">​</a></h5><p>Call Stack 窗口还原当前函数调用链，配合栈上变量逐层检查。依赖栈帧完整，开优化后可能失真。</p><h5 id="_2-5-2-hardfault-现场" tabindex="-1">2.5.2 HardFault 现场 <a class="header-anchor" href="#_2-5-2-hardfault-现场" aria-label="Permalink to &quot;2.5.2 HardFault 现场&quot;">​</a></h5><p>程序跑飞的终极手段，思路三步：</p><p>（1）读故障寄存器（<code>SCB-&gt;CFSR</code>/<code>HFSR</code>/<code>BFAR</code>/<code>MMFAR</code>）确定异常类型：取指出错、访存越界还是未对齐</p><p>（2）从入栈栈帧（R0-R3、R12、LR、PC、xPSR）取出错瞬间的 PC</p><p>（3）PC 对照 map 文件/反汇编定位到源码行（可用 .ini 脚本在停机时自动打印）</p><h3 id="_3-通道二-芯片内统计" tabindex="-1">3. 通道二：芯片内统计 <a class="header-anchor" href="#_3-通道二-芯片内统计" aria-label="Permalink to &quot;3. 通道二：芯片内统计&quot;">​</a></h3><p>不停机，但拿到的不是连续数据，而是<strong>计数器或统计值</strong>。开销最小，适合性能与调度分析。</p><h4 id="_3-1-dwt-周期计数-cyccnt" tabindex="-1">3.1 DWT 周期计数（CYCCNT） <a class="header-anchor" href="#_3-1-dwt-周期计数-cyccnt" aria-label="Permalink to &quot;3.1 DWT 周期计数（CYCCNT）&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>能查什么</td><td>一段代码执行了多少个 CPU 时钟（72 MHz 下 1 µs = 72 计数）</td></tr><tr><td>前提</td><td>SWD（DWT 是内核寄存器，不需要 trace 引脚）</td></tr><tr><td>代价</td><td>需在代码里读 <code>DWT-&gt;CYCCNT</code>，有侵入；不产生波形</td></tr><tr><td>本工程</td><td>试过用它做 <code>delay_us</code>，后改用 SysTick 摘取法（与 bootloader 同源）</td></tr></tbody></table><h4 id="_3-2-pc-采样与性能计数器" tabindex="-1">3.2 PC 采样与性能计数器 <a class="header-anchor" href="#_3-2-pc-采样与性能计数器" aria-label="Permalink to &quot;3.2 PC 采样与性能计数器&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>能查什么</td><td>程序大部分时间花在哪个函数（统计热点），以及 CPI/异常/睡眠等事件计数</td></tr><tr><td>前提</td><td>轮询读 <code>DWT_PCSR</code> 走 SWD 即可；要连续流才需要 SWO</td></tr><tr><td>代价</td><td>采样是统计值，有偏差；轮询采样率受 SWD 往返带宽限制</td></tr><tr><td>注意</td><td>采样周期若与循环周期成整数倍，会一直采到同一条指令</td></tr></tbody></table><h4 id="_3-3-freertos-运行时间统计" tabindex="-1">3.3 FreeRTOS 运行时间统计 <a class="header-anchor" href="#_3-3-freertos-运行时间统计" aria-label="Permalink to &quot;3.3 FreeRTOS 运行时间统计&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>能查什么</td><td>每个任务的 CPU 占比、切换频率（<code>ps</code>/<code>top</code> 命令）</td></tr><tr><td>前提</td><td>只需一个定时器做时基（本工程 TIM7），<strong>不占引脚</strong></td></tr><tr><td>代价</td><td>纯软件统计，精度取决于定时器分辨率（本工程 1 ms）</td></tr><tr><td>本工程</td><td>已启用（<code>configGENERATE_RUN_TIME_STATS = 1</code>）</td></tr></tbody></table><h3 id="_4-通道三-芯片外送" tabindex="-1">4. 通道三：芯片外送 <a class="header-anchor" href="#_4-通道三-芯片外送" aria-label="Permalink to &quot;4. 通道三：芯片外送&quot;">​</a></h3><p>不停机、连续输出，是排查&quot;时序与先后关系&quot;的主力。四种手段的区别只在<strong>走哪条通道</strong>：串口、SWO 引脚、还是调试器后台搬运。</p><h4 id="_4-1-串口-printf" tabindex="-1">4.1 串口 printf <a class="header-anchor" href="#_4-1-串口-printf" aria-label="Permalink to &quot;4.1 串口 printf&quot;">​</a></h4><h5 id="_4-1-1-重定向原理" tabindex="-1">4.1.1 重定向原理 <a class="header-anchor" href="#_4-1-1-重定向原理" aria-label="Permalink to &quot;4.1.1 重定向原理&quot;">​</a></h5><p>MDK 下 <code>printf</code> 最终调用 <code>fputc</code>，重写这个函数把字符送进 USART 发送寄存器，工程一般勾选 microLIB 以缩小 printf 的代码与栈开销。日志自带时间戳（配一个时基），就能记录变量、状态迁移与执行顺序。</p><h5 id="_4-1-2-带宽与阻塞" tabindex="-1">4.1.2 带宽与阻塞 <a class="header-anchor" href="#_4-1-2-带宽与阻塞" aria-label="Permalink to &quot;4.1.2 带宽与阻塞&quot;">​</a></h5><ul><li>前提：一个 USART + USB-TTL（本工程 USART1，PA9/PA10）</li><li>代价：阻塞式发送占 CPU（应换 DMA）；115200 波特率约 11 KB/s，大量输出会拖慢系统甚至改变时序</li></ul><h4 id="_4-2-itm-swo" tabindex="-1">4.2 ITM / SWO <a class="header-anchor" href="#_4-2-itm-swo" aria-label="Permalink to &quot;4.2 ITM / SWO&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>能查什么</td><td>与 printf 同级的日志，但走 SWO 引脚，不占串口</td></tr><tr><td>前提</td><td><strong>PB3（TRACESWO）</strong> + 支持 SWO 的探针（J-Link、板载 ST-Link V2-1）</td></tr><tr><td>代价</td><td>CubeMX 要把 Debug 改成 <code>Trace Asynchronous SW</code>；单向输出、带宽有限</td></tr><tr><td>本工程</td><td>未启用（PB3 空闲，随时可开）</td></tr></tbody></table><h4 id="_4-3-segger-rtt" tabindex="-1">4.3 SEGGER RTT <a class="header-anchor" href="#_4-3-segger-rtt" aria-label="Permalink to &quot;4.3 SEGGER RTT&quot;">​</a></h4><h5 id="_4-3-1-工作原理" tabindex="-1">4.3.1 工作原理 <a class="header-anchor" href="#_4-3-1-工作原理" aria-label="Permalink to &quot;4.3.1 工作原理&quot;">​</a></h5><p>在 RAM 里开一块约 2 KB 的环形缓冲，程序把日志写进缓冲就返回（几乎零阻塞），J-Link 通过调试接口在 <strong>CPU 全速运行的同时</strong>后台把缓冲搬走。本质是&quot;借用通道一的 SWD 访问，干通道三的事&quot;，所以不需要额外引脚。</p><h5 id="_4-3-2-前提与代价" tabindex="-1">4.3.2 前提与代价 <a class="header-anchor" href="#_4-3-2-前提与代价" aria-label="Permalink to &quot;4.3.2 前提与代价&quot;">​</a></h5><ul><li>前提：SWD + J-Link 系探针 + 约 2 KB RAM 缓冲</li><li>代价：需移植 <code>SEGGER_RTT.c</code>；绑定 J-Link 生态</li><li>本工程：未集成，可加（与现有 printf 并存）</li></ul><h4 id="_4-4-semihosting-半主机" tabindex="-1">4.4 Semihosting（半主机） <a class="header-anchor" href="#_4-4-semihosting-半主机" aria-label="Permalink to &quot;4.4 Semihosting（半主机）&quot;">​</a></h4><p>printf/文件 I/O 经调试器（如 MDK）转发到 PC。<strong>每次输出都要让 CPU 停下来等调试器应答</strong>，实时性被彻底破坏——了解即可，绝不可用于时序分析。</p><h3 id="_5-通道四-芯片外测量" tabindex="-1">5. 通道四：芯片外测量 <a class="header-anchor" href="#_5-通道四-芯片外测量" aria-label="Permalink to &quot;5. 通道四：芯片外测量&quot;">​</a></h3><p>数据根本不经过芯片的调试单元，而是用探头直接量引脚电平。这是<strong>唯一能拿到真实波形</strong>的一类。</p><h4 id="_5-1-gpio-打点-逻辑分析仪" tabindex="-1">5.1 GPIO 打点 + 逻辑分析仪 <a class="header-anchor" href="#_5-1-gpio-打点-逻辑分析仪" aria-label="Permalink to &quot;5.1 GPIO 打点 + 逻辑分析仪&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>能查什么</td><td>真实引脚电平与时间关系（微秒级、硬件连续采样，能抓到毛刺）</td></tr><tr><td>前提</td><td>任意空闲 GPIO + 外接逻辑分析仪（几十元起）</td></tr><tr><td>代价</td><td>要改代码打点、要额外硬件；分析仪通道数有限</td></tr></tbody></table><h4 id="_5-2-与示波器的分工" tabindex="-1">5.2 与示波器的分工 <a class="header-anchor" href="#_5-2-与示波器的分工" aria-label="Permalink to &quot;5.2 与示波器的分工&quot;">​</a></h4><p>逻辑分析仪看多路数字时序；要看模拟量（ADC 输入、电源纹波、信号完整性）就得换示波器。两者互补，不互相替代。</p><h3 id="_6-横切-可视化前端" tabindex="-1">6. 横切：可视化前端 <a class="header-anchor" href="#_6-横切-可视化前端" aria-label="Permalink to &quot;6. 横切：可视化前端&quot;">​</a></h3><p>这三个工具都只负责&quot;把已经取到的数据画出来&quot;，<strong>不产生新的数据来路</strong>，因此不构成第五条通道。</p><h4 id="_6-1-j-scope" tabindex="-1">6.1 J-Scope <a class="header-anchor" href="#_6-1-j-scope" aria-label="Permalink to &quot;6.1 J-Scope&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据来路</td><td>通道二/三：SWD 实时采样（或 RTT）</td></tr><tr><td>能查什么</td><td>变量随时间变化的曲线</td></tr><tr><td>前提</td><td>SWD（J-Link）</td></tr><tr><td>代价</td><td>GUI 工具，采样率受 SWD 带宽限制</td></tr></tbody></table><h4 id="_6-2-systemview" tabindex="-1">6.2 SystemView <a class="header-anchor" href="#_6-2-systemview" aria-label="Permalink to &quot;6.2 SystemView&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据来路</td><td>通道三：RTT</td></tr><tr><td>能查什么</td><td>任务切换、中断、API 调用的时间轴（RTOS 级可视化）</td></tr><tr><td>前提</td><td>J-Link + RTT 通道</td></tr><tr><td>代价</td><td>需集成 SEGGER 跟踪库；开销比 printf 小</td></tr></tbody></table><h4 id="_6-3-mdk-logic-analyzer" tabindex="-1">6.3 MDK Logic Analyzer <a class="header-anchor" href="#_6-3-mdk-logic-analyzer" aria-label="Permalink to &quot;6.3 MDK Logic Analyzer&quot;">​</a></h4><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据来路</td><td>通道一：调试器轮询采样（不是硬件连续采样）</td></tr><tr><td>能查什么</td><td>变量/引脚的方波图</td></tr><tr><td>前提</td><td>仿真模式无需硬件；真机需调试器，几十毫秒采一次</td></tr><tr><td>代价</td><td>真机下看不到毛刺、无法命令行导出</td></tr></tbody></table><h2 id="三、-选型与实践" tabindex="-1">三、 选型与实践 <a class="header-anchor" href="#三、-选型与实践" aria-label="Permalink to &quot;三、 选型与实践&quot;">​</a></h2><h3 id="_1-选型三步" tabindex="-1">1. 选型三步 <a class="header-anchor" href="#_1-选型三步" aria-label="Permalink to &quot;1. 选型三步&quot;">​</a></h3><p>拿到问题先别翻工具箱，按顺序回答三个问题：</p><p>（1）<strong>能不能停机</strong>。停机不影响复现（逻辑错误、状态错误）→ 通道一，拿完整现场最省事；停机会破坏现象（时序、调度、通信协议）→ 只能走跟踪类通道</p><p>（2）<strong>要统计值还是连续流</strong>。只要结论（哪里最耗时、谁占 CPU）→ 通道二，开销最小；要看过程与先后关系 → 通道三/四</p><p>（3）<strong>引脚与硬件预算</strong>。串口被业务占用、引脚不富余时，优先 RTT（复用 SWD）；需要真实波形（SPI/I2C、毛刺）直接上逻辑分析仪</p><h3 id="_2-按现象查手段" tabindex="-1">2. 按现象查手段 <a class="header-anchor" href="#_2-按现象查手段" aria-label="Permalink to &quot;2. 按现象查手段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>首选</th><th>备选</th></tr></thead><tbody><tr><td>程序跑飞、进 HardFault</td><td>断点 + Call Stack + Fault 寄存器</td><td>串口打点记录最后状态</td></tr><tr><td>变量莫名被改</td><td>数据观察点（DWT）</td><td>在所有写处打断点</td></tr><tr><td>时序/先后关系不清</td><td>串口 printf 时间戳</td><td>GPIO 打点 + 逻辑分析仪</td></tr><tr><td>任务调度异常、饥饿</td><td>SystemView</td><td>运行时间统计（<code>ps</code>/<code>top</code>）</td></tr><tr><td>CPU 热点（哪里最耗时）</td><td>DWT CYCCNT 计时</td><td>PC 采样、J-Scope</td></tr><tr><td>外设波形（SPI/I2C）</td><td>外接逻辑分析仪</td><td>打点后看 GPIO 翻转</td></tr><tr><td>长时间运行观察（不能停）</td><td>串口 printf / RTT</td><td>SWO</td></tr><tr><td>串口被业务占满</td><td>RTT 或 SWO</td><td>临时复用调试串口</td></tr></tbody></table><h3 id="_3-引脚与硬件开销" tabindex="-1">3. 引脚与硬件开销 <a class="header-anchor" href="#_3-引脚与硬件开销" aria-label="Permalink to &quot;3. 引脚与硬件开销&quot;">​</a></h3><table tabindex="0"><thead><tr><th>手段</th><th>引脚占用</th><th>额外硬件</th><th>属于哪个通道</th></tr></thead><tbody><tr><td>SWD 调试/烧录</td><td>PA13（SWDIO）、PA14（SWCLK）</td><td>J-Link / ST-Link</td><td>一、二</td></tr><tr><td>SWO 跟踪</td><td>再加 PB3（TRACESWO）</td><td>支持 SWO 的探针</td><td>三</td></tr><tr><td>SEGGER RTT</td><td>复用 SWD，不占额外引脚</td><td>J-Link 系探针</td><td>三</td></tr><tr><td>串口 printf</td><td>一个 USART（本工程 PA9/PA10）</td><td>USB-TTL 模块</td><td>三</td></tr><tr><td>GPIO 打点</td><td>任意空闲 GPIO</td><td>外接逻辑分析仪</td><td>四</td></tr><tr><td>软件仿真</td><td>无</td><td>无</td><td>—</td></tr></tbody></table><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',138)])])}const p=d(h,[["render",i]]);export{S as __pageData,p as default};
